4.3 Express 애플리케이션
backend/src/app.js
require(&#039;dotenv&#039;).config();
const express = require(&#039;express&#039;);
const cors = require(&#039;cors&#039;);
const helmet = require(&#039;helmet&#039;);
const rateLimit = require(&#039;express-rate-limit&#039;);
const mysql = require(&#039;mysql2/promise&#039;);
const redis = require(&#039;redis&#039;);

const app = express();
const PORT = process.env.PORT || 5000;

// 미들웨어 설정
app.use(helmet());
app.use(cors({
  origin: process.env.FRONTEND_URL || &#039;http://localhost:3000&#039;,
  credentials: true
}));
app.use(express.json());

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15분
  max: 100 // 최대 100 요청
});
app.use(limiter);

// 데이터베이스 연결 설정
const dbConfig = {
  host: process.env.DB_HOST || &#039;localhost&#039;,
  user: process.env.DB_USER || &#039;root&#039;,
  password: process.env.DB_PASSWORD || &#039;password&#039;,
  database: process.env.DB_NAME || &#039;todoapp&#039;,
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
};

let db;
let redisClient;

// 데이터베이스 연결
async function initializeDatabase() {
  try {
    db = mysql.createPool(dbConfig);
    console.log(&#039;✅ MySQL connected successfully&#039;);
  } catch (error) {
    console.error(&#039;❌ MySQL connection failed:&#039;, error);
    process.exit(1);
  }
}

// Redis 연결
async function initializeRedis() {
  try {
    redisClient = redis.createClient({
      url: `redis://${process.env.REDIS_HOST || &#039;localhost&#039;}:6379`
    });

    await redisClient.connect();
    console.log(&#039;✅ Redis connected successfully&#039;);
  } catch (error) {
    console.error(&#039;❌ Redis connection failed:&#039;, error);
  }
}

// 라우트 정의
app.get(&#039;/health&#039;, (req, res) =&gt; {
  res.json({
    status: &#039;healthy&#039;,
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// 할 일 목록 조회
app.get(&#039;/todos&#039;, async (req, res) =&gt; {
  try {
    // Redis 캐시 확인
    const cached = await redisClient?.get(&#039;todos&#039;);
    if (cached) {
      return res.json(JSON.parse(cached));
    }

    // 데이터베이스에서 조회
    const [rows] = await db.execute(
      &#039;SELECT id, title, description, completed, created_at, updated_at FROM todos ORDER BY created_at DESC&#039;
    );

    // Redis에 캐시 저장 (5분)
    await redisClient?.setEx(&#039;todos&#039;, 300, JSON.stringify(rows));

    res.json(rows);
  } catch (error) {
    console.error(&#039;Error fetching todos:&#039;, error);
    res.status(500).json({ error: &#039;Internal server error&#039; });
  }
});

// 할 일 생성
app.post(&#039;/todos&#039;, async (req, res) =&gt; {
  try {
    const { title, description = &#039;&#039; } = req.body;

    if (!title || title.trim().length === 0) {
      return res.status(400).json({ error: &#039;Title is required&#039; });
    }

    const [result] = await db.execute(
      &#039;INSERT INTO todos (title, description) VALUES (?, ?)&#039;,
      [title.trim(), description.trim()]
    );

    // 캐시 무효화
    await redisClient?.del(&#039;todos&#039;);

    res.status(201).json({
      id: result.insertId,
      title: title.trim(),
      description: description.trim(),
      completed: false,
      created_at: new Date()
    });
  } catch (error) {
    console.error(&#039;Error creating todo:&#039;, error);
    res.status(500).json({ error: &#039;Internal server error&#039; });
  }
});

// 할 일 수정
app.put(&#039;/todos/:id&#039;, async (req, res) =&gt; {
  try {
    const { id } = req.params;
    const { title, description, completed } = req.body;

    const [result] = await db.execute(
      &#039;UPDATE todos SET title = ?, description = ?, completed = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?&#039;,
      [title, description, completed, id]
    );

    if (result.affectedRows === 0) {
      return res.status(404).json({ error: &#039;Todo not found&#039; });
    }

    // 캐시 무효화
    await redisClient?.del(&#039;todos&#039;);

    res.json({ message: &#039;Todo updated successfully&#039; });
  } catch (error) {
    console.error(&#039;Error updating todo:&#039;, error);
    res.status(500).json({ error: &#039;Internal server error&#039; });
  }
});

// 할 일 삭제
app.delete(&#039;/todos/:id&#039;, async (req, res) =&gt; {
  try {
    const { id } = req.params;

    const [result] = await db.execute(&#039;DELETE FROM todos WHERE id = ?&#039;, [id]);

    if (result.affectedRows === 0) {
      return res.status(404).json({ error: &#039;Todo not found&#039; });
    }

    // 캐시 무효화
    await redisClient?.del(&#039;todos&#039;);

    res.json({ message: &#039;Todo deleted successfully&#039; });
  } catch (error) {
    console.error(&#039;Error deleting todo:&#039;, error);
    res.status(500).json({ error: &#039;Internal server error&#039; });
  }
});

// 에러 핸들링 미들웨어
app.use((err, req, res, next) =&gt; {
  console.error(err.stack);
  res.status(500).json({ error: &#039;Something went wrong!&#039; });
});

// 404 핸들러
app.use((req, res) =&gt; {
  res.status(404).json({ error: &#039;Route not found&#039; });
});

// 서버 시작
async function startServer() {
  await initializeDatabase();
  await initializeRedis();

  app.listen(PORT, &#039;0.0.0.0&#039;, () =&gt; {
    console.log(`🚀 Server running on port ${PORT}`);
    console.log(`📊 Health check: http://localhost:${PORT}/health`);
  });
}

// Graceful shutdown
process.on(&#039;SIGTERM&#039;, async () =&gt; {
  console.log(&#039;SIGTERM received, shutting down gracefully&#039;);
  await db?.end();
  await redisClient?.disconnect();
  process.exit(0);
});

process.on(&#039;SIGINT&#039;, async () =&gt; {
  console.log(&#039;SIGINT received, shutting down gracefully&#039;);
  await db?.end();
  await redisClient?.disconnect();
  process.exit(0);
});

startServer().catch(console.error);

4.4 데이터베이스 스키마
backend/init-db/schema.sql
-- 할 일 테이블 생성
CREATE TABLE IF NOT EXISTS todos (
    id INT AUTO_INCREMENT PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    completed BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

-- 사용자 테이블 (향후 확장용)
CREATE TABLE IF NOT EXISTS users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    email VARCHAR(255) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    name VARCHAR(100) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

-- 샘플 데이터 삽입
