frontend/src/App.js
import React, { useState, useEffect } from &#039;react&#039;;
import axios from &#039;axios&#039;;
import toast, { Toaster } from &#039;react-hot-toast&#039;;
import &#039;./App.css&#039;;

const API_URL = process.env.REACT_APP_API_URL || &#039;/api&#039;;

// API 클라이언트 설정
const api = axios.create({
  baseURL: API_URL,
  timeout: 10000,
});

function App() {
  const [todos, setTodos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [newTodo, setNewTodo] = useState({ title: &#039;&#039;, description: &#039;&#039; });

  // 할 일 목록 조회
  const fetchTodos = async () =&gt; {
    try {
      setLoading(true);
      const response = await api.get(&#039;/todos&#039;);
      setTodos(response.data);
    } catch (error) {
      console.error(&#039;Failed to fetch todos:&#039;, error);
      toast.error(&#039;할 일 목록을 불러오는데 실패했습니다.&#039;);
    } finally {
      setLoading(false);
    }
  };

  // 할 일 추가
  const addTodo = async (e) =&gt; {
    e.preventDefault();

    if (!newTodo.title.trim()) {
      toast.error(&#039;제목을 입력해주세요.&#039;);
      return;
    }

    try {
      const response = await api.post(&#039;/todos&#039;, newTodo);
      setTodos([response.data, ...todos]);
      setNewTodo({ title: &#039;&#039;, description: &#039;&#039; });
      toast.success(&#039;할 일이 추가되었습니다.&#039;);
    } catch (error) {
      console.error(&#039;Failed to add todo:&#039;, error);
      toast.error(&#039;할 일 추가에 실패했습니다.&#039;);
    }
  };

  // 할 일 완료 상태 변경
  const toggleTodo = async (id, completed) =&gt; {
    try {
      const todo = todos.find(t =&gt; t.id === id);
      await api.put(`/todos/${id}`, {
        ...todo,
        completed: !completed
      });

      setTodos(todos.map(todo =&gt;
        todo.id === id ? { ...todo, completed: !completed } : todo
      ));

      toast.success(completed ? &#039;할 일을 미완료로 변경했습니다.&#039; : &#039;할 일을 완료했습니다.&#039;);
    } catch (error) {
      console.error(&#039;Failed to toggle todo:&#039;, error);
      toast.error(&#039;할 일 상태 변경에 실패했습니다.&#039;);
    }
  };

  // 할 일 삭제
  const deleteTodo = async (id) =&gt; {
    if (!window.confirm(&#039;정말로 삭제하시겠습니까?&#039;)) {
      return;
    }

    try {
      await api.delete(`/todos/${id}`);
      setTodos(todos.filter(todo =&gt; todo.id !== id));
      toast.success(&#039;할 일이 삭제되었습니다.&#039;);
    } catch (error) {
      console.error(&#039;Failed to delete todo:&#039;, error);
      toast.error(&#039;할 일 삭제에 실패했습니다.&#039;);
    }
  };

  // 컴포넌트 마운트 시 할 일 목록 조회
  useEffect(() =&gt; {
    fetchTodos();
  }, []);

  return (
    &lt;div className=&quot;App&quot;&gt;
      &lt;Toaster position=&quot;top-right&quot; /&gt;

      &lt;header className=&quot;App-header&quot;&gt;
        &lt;h1&gt;📝 할 일 관리&lt;/h1&gt;
        &lt;p&gt;Docker Compose로 구성한 풀스택 애플리케이션&lt;/p&gt;
      &lt;/header&gt;

      &lt;main className=&quot;main-content&quot;&gt;
        {/* 할 일 추가 폼 */}
        &lt;section className=&quot;add-todo-section&quot;&gt;
          &lt;h2&gt;새 할 일 추가&lt;/h2&gt;
          &lt;form onSubmit={addTodo} className=&quot;add-todo-form&quot;&gt;
            &lt;div className=&quot;form-group&quot;&gt;
              &lt;input
                type=&quot;text&quot;
                placeholder=&quot;할 일 제목을 입력하세요&quot;
                value={newTodo.title}
                onChange={(e) =&gt; setNewTodo({ ...newTodo, title: e.target.value })}
                className=&quot;form-input&quot;
              /&gt;
            &lt;/div&gt;
            &lt;div className=&quot;form-group&quot;&gt;
              &lt;textarea
                placeholder=&quot;상세 설명 (선택사항)&quot;
                value={newTodo.description}
                onChange={(e) =&gt; setNewTodo({ ...newTodo, description: e.target.value })}
                className=&quot;form-textarea&quot;
                rows=&quot;3&quot;
              /&gt;
            &lt;/div&gt;
            &lt;button type=&quot;submit&quot; className=&quot;btn btn-primary&quot;&gt;
              추가하기
            &lt;/button&gt;
          &lt;/form&gt;
        &lt;/section&gt;

        {/* 할 일 목록 */}
        &lt;section className=&quot;todos-section&quot;&gt;
          &lt;h2&gt;할 일 목록 ({todos.length}개)&lt;/h2&gt;

          {loading ? (
            &lt;div className=&quot;loading&quot;&gt;로딩 중...&lt;/div&gt;
          ) : todos.length === 0 ? (
            &lt;div className=&quot;empty-state&quot;&gt;
              &lt;p&gt;할 일이 없습니다. 새로운 할 일을 추가해보세요!&lt;/p&gt;
            &lt;/div&gt;
          ) : (
            &lt;div className=&quot;todos-grid&quot;&gt;
              {todos.map(todo =&gt; (
                &lt;div
                  key={todo.id}
                  className={`todo-card ${todo.completed ? &#039;completed&#039; : &#039;&#039;}`}
                &gt;
                  &lt;div className=&quot;todo-content&quot;&gt;
                    &lt;h3 className=&quot;todo-title&quot;&gt;{todo.title}&lt;/h3&gt;
                    {todo.description &amp;&amp; (
                      &lt;p className=&quot;todo-description&quot;&gt;{todo.description}&lt;/p&gt;
                    )}
                    &lt;div className=&quot;todo-meta&quot;&gt;
                      &lt;span className=&quot;todo-date&quot;&gt;
                        생성일: {new Date(todo.created_at).toLocaleDateString(&#039;ko-KR&#039;)}
                      &lt;/span&gt;
                      {todo.updated_at !== todo.created_at &amp;&amp; (
                        &lt;span className=&quot;todo-date&quot;&gt;
                          수정일: {new Date(todo.updated_at).toLocaleDateString(&#039;ko-KR&#039;)}
                        &lt;/span&gt;
                      )}
                    &lt;/div&gt;
                  &lt;/div&gt;

                  &lt;div className=&quot;todo-actions&quot;&gt;
                    &lt;button
                      onClick={() =&gt; toggleTodo(todo.id, todo.completed)}
                      className={`btn ${todo.completed ? &#039;btn-warning&#039; : &#039;btn-success&#039;}`}
                    &gt;
                      {todo.completed ? &#039;미완료&#039; : &#039;완료&#039;}
                    &lt;/button&gt;
                    &lt;button
                      onClick={() =&gt; deleteTodo(todo.id)}
                      className=&quot;btn btn-danger&quot;
                    &gt;
                      삭제
                    &lt;/button&gt;
                  &lt;/div&gt;
                &lt;/div&gt;
              ))}
            &lt;/div&gt;
          )}
        &lt;/section&gt;
      &lt;/main&gt;

      &lt;footer className=&quot;App-footer&quot;&gt;
        &lt;p&gt;🐳 Docker Compose 풀스택 애플리케이션 예제&lt;/p&gt;
        &lt;div className=&quot;tech-stack&quot;&gt;
          &lt;span&gt;React&lt;/span&gt;
          &lt;span&gt;Node.js&lt;/span&gt;
          &lt;span&gt;MySQL&lt;/span&gt;
          &lt;span&gt;Redis&lt;/span&gt;
          &lt;span&gt;Nginx&lt;/span&gt;
        &lt;/div&gt;
      &lt;/footer&gt;
    &lt;/div&gt;
  );
}

export default App;

