실습 3: Lambda 함수 코드 작성
3.1 사용자 관리 API 코드
Lambda 함수의 코드를 다음으로 교체:
import json
import boto3
from decimal import Decimal
from datetime import datetime

# DynamoDB 클라이언트 초기화
dynamodb = boto3.resource(&#039;dynamodb&#039;)
table = dynamodb.Table(&#039;Users&#039;)

# Decimal을 JSON으로 변환하기 위한 헬퍼 클래스
class DecimalEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Decimal):
            return float(obj)
        return super(DecimalEncoder, self).default(obj)

def lambda_handler(event, context):
    print(&quot;Received event:&quot;, json.dumps(event))

    http_method = event.get(&#039;httpMethod&#039;)
    path = event.get(&#039;path&#039;, &#039;&#039;)

    try:
        # 라우팅
        if http_method == &#039;POST&#039; and path == &#039;/users&#039;:
            return create_user(event)
        elif http_method == &#039;GET&#039; and path == &#039;/users&#039;:
            return get_all_users(event)
        elif http_method == &#039;GET&#039; and path.startswith(&#039;/users/&#039;):
            return get_user(event)
        elif http_method == &#039;PUT&#039; and path.startswith(&#039;/users/&#039;):
            return update_user(event)
        elif http_method == &#039;DELETE&#039; and path.startswith(&#039;/users/&#039;):
            return delete_user(event)
        else:
            return response(400, {&#039;error&#039;: &#039;Unsupported route&#039;})

    except Exception as e:
        print(f&quot;Error: {str(e)}&quot;)
        return response(500, {&#039;error&#039;: str(e)})

# 사용자 생성
def create_user(event):
    body = json.loads(event.get(&#039;body&#039;, &#039;{}&#039;))

    user_id = body.get(&#039;userId&#039;)
    name = body.get(&#039;name&#039;)
    email = body.get(&#039;email&#039;)

    if not user_id or not name or not email:
        return response(400, {&#039;error&#039;: &#039;userId, name, email are required&#039;})

    item = {
        &#039;userId&#039;: user_id,
        &#039;name&#039;: name,
        &#039;email&#039;: email,
        &#039;createdAt&#039;: datetime.now().isoformat()
    }

    table.put_item(Item=item)

    return response(201, {
        &#039;message&#039;: &#039;User created successfully&#039;,
        &#039;user&#039;: item
    })

# 모든 사용자 조회
def get_all_users(event):
    result = table.scan()
    users = result.get(&#039;Items&#039;, [])

    return response(200, {
        &#039;count&#039;: len(users),
        &#039;users&#039;: users
    })

# 특정 사용자 조회
def get_user(event):
    path = event.get(&#039;path&#039;, &#039;&#039;)
    user_id = path.split(&#039;/&#039;)[-1]

    result = table.get_item(Key={&#039;userId&#039;: user_id})

    if &#039;Item&#039; not in result:
        return response(404, {&#039;error&#039;: &#039;User not found&#039;})

    return response(200, {&#039;user&#039;: result[&#039;Item&#039;]})

# 사용자 정보 수정
def update_user(event):
    path = event.get(&#039;path&#039;, &#039;&#039;)
    user_id = path.split(&#039;/&#039;)[-1]

    body = json.loads(event.get(&#039;body&#039;, &#039;{}&#039;))
    name = body.get(&#039;name&#039;)
    email = body.get(&#039;email&#039;)

    if not name and not email:
        return response(400, {&#039;error&#039;: &#039;At least one field (name or email) is required&#039;})

    # 업데이트할 필드 구성
    update_expression = &quot;SET &quot;
    expression_values = {}

    if name:
        update_expression += &quot;name = :name, &quot;
        expression_values[&#039;:name&#039;] = name
    if email:
        update_expression += &quot;email = :email, &quot;
        expression_values[&#039;:email&#039;] = email

    update_expression = update_expression.rstrip(&#039;, &#039;)

    table.update_item(
        Key={&#039;userId&#039;: user_id},
        UpdateExpression=update_expression,
        ExpressionAttributeValues=expression_values
    )

    return response(200, {
        &#039;message&#039;: &#039;User updated successfully&#039;,
        &#039;userId&#039;: user_id
    })

# 사용자 삭제
def delete_user(event):
    path = event.get(&#039;path&#039;, &#039;&#039;)
    user_id = path.split(&#039;/&#039;)[-1]

    table.delete_item(Key={&#039;userId&#039;: user_id})

    return response(200, {
        &#039;message&#039;: &#039;User deleted successfully&#039;,
        &#039;userId&#039;: user_id
    })

# HTTP 응답 생성 헬퍼 함수
def response(status_code, body):
    return {
